  for (let i = 0; i < 2600; i++) {
    const y = rand() * size;
    const x = rand() * size;
    const len = 10 + rand() * 90;
    const v = Math.floor(80 + rand() * 130);
    ctx.strokeStyle = 'rgba(' + v + ',' + v + ',' + v + ',' + (0.12 + rand() * 0.35).toFixed(3) + ')';
