// ---------------------------------------------------------------------------
// Prince Rupert's Drop spine, parameterised by normalised arc length s in [0,1]
// (s = 0 bulb pole at the bottom, s = 1 helical tail tip at the top)
// ---------------------------------------------------------------------------
function spineRaw(t, out) {
  const y0 = -1.72, y1 = 1.52;
  const y = y0 + (y1 - y0) * t;
  const lean = 0.46 * t * t;                 // gentle diagonal lean to the right
  const u = smoothstep(0.70, 1.0, t);        // helical tail region
  const hr = 0.17 * u;
  const ang = u * Math.PI * 2.5;
  out.set(lean + hr * (Math.cos(ang) - 1.0), y, hr * Math.sin(ang));
  return out;
}
const spineTable = (() => {
  const N = 2400;
  const pts = new Array(N + 1);
  const cum = new Float64Array(N + 1);
  for (let i = 0; i <= N; i++) {
    pts[i] = spineRaw(i / N, new THREE.Vector3());
    if (i > 0) cum[i] = cum[i - 1] + pts[i].distanceTo(pts[i - 1]);
  }
  return { pts, cum, length: cum[N], N };
})();
const SPINE_LEN = spineTable.length;
const BULB_R = 0.56;
const S_IMPACT = BULB_R / SPINE_LEN;        // bulb centre (impact site) as spine parameter

function spinePoint(s, out) {
  const d = clamp01(s) * SPINE_LEN;
  const cum = spineTable.cum;
  let lo = 0, hi = spineTable.N;
  while (hi - lo > 1) { const mid = (lo + hi) >> 1; if (cum[mid] <= d) lo = mid; else hi = mid; }
  const seg = cum[hi] - cum[lo];
  const f = seg > 1e-9 ? (d - cum[lo]) / seg : 0;
  return out.copy(spineTable.pts[lo]).lerp(spineTable.pts[hi], f);
}
const _ta = new THREE.Vector3(), _tb = new THREE.Vector3();
function spineTangent(s, out) {
  const e = 0.002;
  spinePoint(Math.max(0, s - e), _ta);
  spinePoint(Math.min(1, s + e), _tb);
  return out.subVectors(_tb, _ta).normalize();
}
function smax(a, b, k) { const h = clamp01(0.5 + 0.5 * (a - b) / k); return lerp(b, a, h) + k * h * (1 - h); }
function dropRadius(s) {
  const d = clamp01(s) * SPINE_LEN;
  const R = BULB_R;
  const sph = d < 2 * R ? Math.sqrt(Math.max(0, R * R - (d - R) * (d - R))) : 0;
  const neck = (0.125 * Math.exp(-Math.max(0, d - 0.84) * 0.95) + 0.021) * smoothstep(0.3, 0.9, d);
  let r = smax(sph, neck, 0.16);
  r *= 0.08 + 0.92 * smoothstep(1.0, 0.985, s);   // needle point at the very tip
  return Math.max(r, 0.002);
}

// Camera framing: fixed, looking along -Z, drop within the central 70% for 16:9 and 1280x1340
const dropBounds = (() => {
  const b = new THREE.Box3();
  const p = new THREE.Vector3();
  for (let i = 0; i <= 400; i++) {
    const s = i / 400;
    spinePoint(s, p);
    const r = dropRadius(s);
    b.expandByPoint(new THREE.Vector3(p.x - r, p.y - r, p.z - r));
    b.expandByPoint(new THREE.Vector3(p.x + r, p.y + r, p.z + r));
  }
  return b;
})();
const CAM_TARGET = dropBounds.getCenter(new THREE.Vector3());
CAM_TARGET.z = 0;
const CAM_DIST = (() => {
  const size = dropBounds.getSize(new THREE.Vector3());
  const tanHalf = Math.tan(THREE.MathUtils.degToRad(35) * 0.5);
  const needH = size.y / (0.66 * 2 * tanHalf);
  const needW = size.x / (0.66 * 2 * tanHalf * (1280 / 1340));
  return Math.max(needH, needW) + 0.4;
})();
camera.position.set(CAM_TARGET.x, CAM_TARGET.y, CAM_DIST);
camera.lookAt(CAM_TARGET);
camera.updateMatrixWorld();

// ---------------------------------------------------------------------------
// Tube geometry along the spine with per-vertex spine attributes
// ---------------------------------------------------------------------------
const SEGS = 48;
function buildTubeGeometry(s0, s1, rings) {
  const nv = (rings + 1) * (SEGS + 1);
  const pos = new Float32Array(nv * 3), nor = new Float32Array(nv * 3);
  const aS = new Float32Array(nv), aR = new Float32Array(nv);
  const aC = new Float32Array(nv * 3), aT = new Float32Array(nv * 3), aN1 = new Float32Array(nv * 3);
  const C = new THREE.Vector3(), T = new THREE.Vector3(), prevT = new THREE.Vector3();
  const N1 = new THREE.Vector3(), N2 = new THREE.Vector3(), tmp = new THREE.Vector3(), axis = new THREE.Vector3();
  let vi = 0;
  for (let i = 0; i <= rings; i++) {
