// ---------------------------------------------------------------------------
const KINETIC_GLSL = `
attribute vec3 aP0; attribute vec3 aVel; attribute vec4 aRot; attribute vec4 aMisc;
uniform float uTime; uniform vec3 uGravity; uniform float uDrag; uniform float uRotDrag;
mat3 kineticAxisRot(vec3 ax, float a) {
  float c = cos(a), s = sin(a), oc = 1.0 - c;
  return mat3(oc * ax.x * ax.x + c, oc * ax.x * ax.y + ax.z * s, oc * ax.z * ax.x - ax.y * s,
              oc * ax.x * ax.y - ax.z * s, oc * ax.y * ax.y + c, oc * ax.y * ax.z + ax.x * s,
              oc * ax.z * ax.x + ax.y * s, oc * ax.y * ax.z - ax.x * s, oc * ax.z * ax.z + c);
}
mat3 kineticRot; vec3 kineticPos; float kineticScale;
void kinetic() {
  float tau = uTime - aMisc.x;
  float alive = step(0.0, tau);
  tau = max(tau, 0.0);
  float ek = exp(-uDrag * tau);
  vec3 disp = aVel * (1.0 - ek) / uDrag + uGravity * (tau - (1.0 - ek) / uDrag) / uDrag;
  kineticPos = aP0 + disp;
  float ang = aRot.w * (1.0 - exp(-uRotDrag * tau)) / uRotDrag;
  kineticRot = kineticAxisRot(normalize(aRot.xyz), ang);
  kineticScale = alive * smoothstep(0.0, 0.05, tau);
