// ---------------------------------------------------------------------------
// Lead/copper bullet with plastic mushrooming (vertex-shader deformation)
// ---------------------------------------------------------------------------
const BULLET_R = 0.15, BULLET_LEN = 0.78;
const bulletGeom = (() => {
  const pts = [];
  const n = 40;
  for (let i = 0; i <= n; i++) {
    const y = (i / n) * BULLET_LEN;
    let r;
    if (y < 0.34) r = BULLET_R * Math.pow(Math.sin(0.5 * Math.PI * y / 0.34), 0.72);
    else if (y < 0.70) r = BULLET_R;
    else r = BULLET_R * (1 - 0.22 * (y - 0.70) / (BULLET_LEN - 0.70));
    pts.push(new THREE.Vector2(i === 0 ? 0 : Math.max(0.0005, r), y));
  }
  const g = new THREE.LatheGeometry(pts, 48);
  g.rotateZ(-Math.PI / 2);   // nose at the origin, base at +X, flying toward -X
  const pos = g.getAttribute('position');
  const col = new Float32Array(pos.count * 3);
  for (let i = 0; i < pos.count; i++) {
    const lead = (pos.getX(i) / BULLET_LEN) < 0.42;   // dull lead nose, copper jacket behind
    col[i * 3] = lead ? 0.58 : 0.80;
    col[i * 3 + 1] = lead ? 0.60 : 0.50;
    col[i * 3 + 2] = lead ? 0.64 : 0.30;
  }
  g.setAttribute('color', new THREE.BufferAttribute(col, 3));
  return g;
})();
const bulletUniforms = { uMush: { value: 0 } };
const bulletMat = new THREE.MeshStandardMaterial({ color: 0xffffff, vertexColors: true, metalness: 0.95, roughness: 0.38, envMapIntensity: 1.2 });
bulletMat.onBeforeCompile = function (shader) {
  shader.uniforms.uMush = bulletUniforms.uMush;
  shader.vertexShader = 'uniform float uMush;\n' + shader.vertexShader
    .replace('#include <beginnormal_vertex>', [
      'float bAx = clamp(position.x / ' + BULLET_LEN.toFixed(4) + ', 0.0, 1.0);',
      'float bFront = pow(1.0 - bAx, 1.6);',
      'vec3 objectNormal = normalize(mix(normal, normalize(vec3(normal.x - 1.6 * bFront, normal.yz)), uMush));'
    ].join('\n'))
    .replace('#include <begin_vertex>', [
      'float bAxNew = mix(bAx, pow(bAx, 1.5) * 0.42, uMush);',
      'float bExpand = 1.0 + uMush * 2.4 * bFront;',
      'vec3 transformed = vec3(bAxNew * ' + BULLET_LEN.toFixed(4) + ', position.yz * bExpand);'
    ].join('\n'));
};
bulletMat.customProgramCacheKey = function () { return 'bullet'; };
const bullet = new THREE.Mesh(bulletGeom, bulletMat);
scene.add(bullet);
fillDroplets(IMPACT_X, P_IMPACT_CENTER.y);
fillImpactSpray(IMPACT_X, P_IMPACT_CENTER.y);

// ---------------------------------------------------------------------------
// Articulated brushed-steel nippers at the upper tail tip
// Local frame: origin at the cut point, +X toward the pivot, +Y closing axis,
// +Z along the tail tangent (parallel to the cutting edges).
// ---------------------------------------------------------------------------
const steelMat = new THREE.MeshStandardMaterial({
  color: 0xb4bac3, metalness: 1.0, roughness: 0.42, roughnessMap: brushedTex,
  bumpMap: brushedTex, bumpScale: 0.003, envMapIntensity: 1.25
});
const gripMat = new THREE.MeshStandardMaterial({ color: 0x15171c, metalness: 0.1, roughness: 0.85 });
const HINGE = 0.82;
function jawShape(mirror) {
  const pts = [[0.0, 0.07], [-0.12, 0.19], [-0.5, 0.21], [-0.78, 0.17], [-0.98, 0.06], [-0.99, 0.0], [-0.62, 0.0], [-0.3, 0.035]];
  const shape = new THREE.Shape();
  pts.forEach((pt, i) => {
    const yy = mirror ? -pt[1] : pt[1];
    if (i === 0) shape.moveTo(pt[0], yy); else shape.lineTo(pt[0], yy);
  });
  shape.closePath();
  return shape;
}
function bar(x0, y0, x1, y1, rad, mat) {
  const len = Math.hypot(x1 - x0, y1 - y0);
  const m = new THREE.Mesh(new THREE.CylinderGeometry(rad, rad * 0.9, len, 18, 1), mat);
  m.position.set((x0 + x1) / 2, (y0 + y1) / 2, 0);
  m.rotation.z = Math.atan2(y1 - y0, x1 - x0) - Math.PI / 2;
  return m;
}
function makeJawPiece(mirror) {
  const piece = new THREE.Group();
  const jawGeo = new THREE.ExtrudeGeometry(jawShape(mirror), { depth: 0.15, bevelEnabled: true, bevelThickness: 0.012, bevelSize: 0.01, bevelSegments: 2 });
  jawGeo.translate(0, 0, -0.075);
  piece.add(new THREE.Mesh(jawGeo, steelMat));
  const sgn = mirror ? 1 : -1;   // handle sits on the far side of the pivot from its blade
  piece.add(bar(0.02, sgn * 0.05, 1.55, sgn * 0.26, 0.055, steelMat));
  piece.add(bar(1.5, sgn * 0.255, 3.6, sgn * 0.56, 0.075, gripMat));
  return piece;
}
const nipperGroup = new THREE.Group();
const jawA = makeJawPiece(false);
const jawB = makeJawPiece(true);
jawA.position.set(HINGE, 0, 0);
jawB.position.set(HINGE, 0, 0);
const bolt = new THREE.Mesh(new THREE.CylinderGeometry(0.085, 0.085, 0.2, 24), steelMat);
bolt.rotation.x = Math.PI / 2;
bolt.position.set(HINGE, 0, 0);
nipperGroup.add(jawA, jawB, bolt);
const NIP_D = new THREE.Vector3(0.72, 0.1, -0.69);
NIP_D.addScaledVector(T_CUT, -NIP_D.dot(T_CUT)).normalize();
const NIP_C = new THREE.Vector3().crossVectors(T_CUT, NIP_D).normalize();
nipperGroup.quaternion.setFromRotationMatrix(new THREE.Matrix4().makeBasis(NIP_D, NIP_C, T_CUT));
nipperGroup.position.copy(P_CUT);
scene.add(nipperGroup);

// ---------------------------------------------------------------------------
// Fine dark-anodized suspension: wire loop around the neck, rising off-frame
// ---------------------------------------------------------------------------
const S_LOOP = 0.46;
const loopPos = spinePoint(S_LOOP, new THREE.Vector3());
const loopT = spineTangent(S_LOOP, new THREE.Vector3());
const loopR = dropRadius(S_LOOP) + 0.012;
const wireMat = new THREE.MeshStandardMaterial({ color: 0x1b1d22, metalness: 0.85, roughness: 0.4, envMapIntensity: 0.9 });
const loop = new THREE.Mesh(new THREE.TorusGeometry(loopR, 0.007, 10, 48), wireMat);
loop.position.copy(loopPos);
loop.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), loopT);
scene.add(loop);
const wireAnchor = new THREE.Vector3(loopPos.x - 0.42, 4.4, loopPos.z - 0.1);
const loopTop = loopPos.clone().add(new THREE.Vector3(0, loopR, 0));
const wireDir = new THREE.Vector3().subVectors(wireAnchor, loopTop);
const wire = new THREE.Mesh(new THREE.CylinderGeometry(0.0045, 0.0045, wireDir.length(), 8, 1), wireMat);
wire.position.lerpVectors(loopTop, wireAnchor, 0.5);
wire.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), wireDir.clone().normalize());
scene.add(wire);

// ---------------------------------------------------------------------------
// Additive glow sprites (procedural radial texture)
// ---------------------------------------------------------------------------
function makeGlowSprite(color) {
  const m = new THREE.SpriteMaterial({ map: glowTex, color: color, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, depthTest: false });
  const s = new THREE.Sprite(m);
  s.renderOrder = 5;
  s.visible = false;
  scene.add(s);
  return s;
}
const flashSprite = makeGlowSprite(0xcfe4ff);
const flashCore = makeGlowSprite(0xffffff);
const frontSprite = makeGlowSprite(0xd0e6ff);
const impactSprite = makeGlowSprite(0xfff1dc);

