  for (let i = 0; i < kineticUniformSets.length; i++) kineticUniformSets[i].uTime.value = t;
  for (let i = 0; i < pointSystems.length; i++) pointSystems[i].uniforms.uTime.value = t;

  // --- Lights and glow sprites ---------------------------------------------
  flashLight.position.copy(P_CUT);
  flashLight.intensity = 10 * flash;
