  setSprite(impactSprite, _pos.set(IMPACT_X, py, 0), 0.25 + 0.6 * impactGlow, impactGlow * 0.9);

  renderer.render(scene, camera);
}

// ---------------------------------------------------------------------------
// Playback state machine: COUNTDOWN -> PLAYING -> ENDED, PAUSED, REFIRE_HOLD
// ---------------------------------------------------------------------------
const State = { COUNTDOWN: 'COUNTDOWN', PLAYING: 'PLAYING', PAUSED: 'PAUSED', REFIRE_HOLD: 'REFIRE_HOLD', ENDED: 'ENDED' };
let state = State.COUNTDOWN;
let simTime = 0;
let playbackSpeed = 1.0;
let countdownElapsed = 0;
let holdElapsed = 0;
let lastNow = null;
let needsRender = false;

function showPauseIcon(playing) {
  iconPause.style.display = playing ? '' : 'none';
  iconPlay.style.display = playing ? 'none' : '';
  btnToggle.setAttribute('aria-label', playing ? 'Pause' : 'Play');
}
function hideCountdown() { elCountdown.style.display = 'none'; elCountdown.textContent = ''; }
function showCountdown(text) { elCountdown.style.display = 'block'; if (elCountdown.textContent !== text) elCountdown.textContent = text; }

function frame(nowMs) {
  requestAnimationFrame(frame);
  const now = nowMs / 1000;
  const dt = lastNow === null ? 0 : Math.min(0.1, Math.max(0, now - lastNow));
  lastNow = now;
  switch (state) {
    case State.COUNTDOWN:
      countdownElapsed += dt;
      if (countdownElapsed >= 3.0) {
        hideCountdown();
        state = State.PLAYING;
        showPauseIcon(true);
      } else {
        showCountdown(countdownElapsed < 1.0 ? '3' : countdownElapsed < 2.0 ? '2' : '1');
      }
      break;
    case State.REFIRE_HOLD:
      holdElapsed += dt;
      if (holdElapsed >= 1.0) state = State.PLAYING;
      break;
    case State.PLAYING:
      simTime = Math.min(DURATION, simTime + dt * playbackSpeed);
      scrubber.value = simTime.toFixed(3);
      needsRender = true;
      if (simTime >= DURATION) {
        simTime = DURATION;
        scrubber.value = DURATION.toFixed(3);
        state = State.ENDED;
        showPauseIcon(false);
      }
      break;
    default:
      break;
  }
  if (needsRender) { needsRender = false; renderAt(simTime); }
}

btnToggle.addEventListener('click', function () {
  switch (state) {
    case State.PLAYING:
      state = State.PAUSED;
      showPauseIcon(false);
      break;
    case State.COUNTDOWN:
    case State.REFIRE_HOLD:
      hideCountdown();
      simTime = 0;
      state = State.PAUSED;
      showPauseIcon(false);
      renderAt(0);
      break;
    case State.PAUSED:
      state = State.PLAYING;
      showPauseIcon(true);
      break;
    case State.ENDED:
      simTime = 0;
      scrubber.value = '0';
      hideCountdown();
      state = State.PLAYING;
      showPauseIcon(true);
      renderAt(0);
      break;
    default:
      break;
  }
});

btnRefire.addEventListener('click', function () {
  hideCountdown();
  countdownElapsed = 0;
  simTime = 0;
  scrubber.value = '0';
  renderAt(0);
  showPauseIcon(true);
  state = State.REFIRE_HOLD;
  holdElapsed = 0;
});

speedPills.forEach(function (pill) {
  pill.addEventListener('click', function () {
    playbackSpeed = parseFloat(pill.getAttribute('data-speed'));
    speedPills.forEach(function (q) {
      const on = q === pill;
      q.classList.toggle('is-active', on);
      q.setAttribute('aria-checked', on ? 'true' : 'false');
    });
  });
});

scrubber.addEventListener('input', function () {
  if (state === State.COUNTDOWN || state === State.REFIRE_HOLD) hideCountdown();
  const v = parseFloat(scrubber.value);
  simTime = Math.max(0, Math.min(DURATION, isNaN(v) ? 0 : v));
  state = State.PAUSED;
  showPauseIcon(false);
  renderAt(simTime);
});

window.addEventListener('resize', function () {
  const w = window.innerWidth, h = window.innerHeight;
  renderer.setSize(w, h, false);
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
  for (let i = 0; i < pointSystems.length; i++) pointSystems[i].uniforms.uPixelRatio.value = renderer.getPixelRatio();
  renderAt(simTime);
});

// Initial resting scene, then the countdown starts on the first animation frame
showCountdown('3');
scrubber.value = '0';
renderAt(0); // INIT-RENDER
requestAnimationFrame(frame);

})();
</script>
