  switch (state) {
    case State.PLAYING:
      state = State.PAUSED;
      showPauseIcon(false);
      break;
    case State.COUNTDOWN:
    case State.REFIRE_HOLD:
      hideCountdown();
      simTime = 0;
      state = State.PAUSED;
      showPauseIcon(false);
      renderAt(0);
      break;
    case State.PAUSED:
      state = State.PLAYING;
      showPauseIcon(true);
      break;
    case State.ENDED:
      simTime = 0;
      scrubber.value = '0';
      hideCountdown();
      state = State.PLAYING;
      showPauseIcon(true);
      renderAt(0);
      break;
    default:
      break;
  }
});

