// ---------------------------------------------------------------------------
// renderAt(simTime): a pure function of simulation time -> rendered frame.
// Every object pose and shader uniform is evaluated analytically from t, so
// forward playback, scrubbing, resets and any display rate yield identical frames.
// ---------------------------------------------------------------------------
const BULLET_V = 5.2;
const _pos = new THREE.Vector3();
const _frontPos = new THREE.Vector3();
const _tipAxis = new THREE.Vector3(0.3, 0.25, 1.0).normalize();
function setSprite(sprite, pos, scale, intensity) {
  if (intensity <= 0.002) { sprite.visible = false; return; }
  sprite.visible = true;
  sprite.position.copy(pos);
  sprite.scale.set(scale, scale, 1);
  sprite.material.opacity = Math.min(1, intensity);
}
function dragDisp(v, k, tau) { return v * (1 - Math.exp(-k * tau)) / k; }
function gravDisp(g, k, tau) { return (g / k) * (tau - (1 - Math.exp(-k * tau)) / k); }

function renderAt(tIn) {
  const t = Math.max(0, Math.min(DURATION, tIn));
  const py = P_IMPACT_CENTER.y;

  // --- Phase 1-2: bullet approach, impact, mushrooming, rebound -----------
  if (t < T_IMPACT) {
    bullet.visible = true;
    bullet.scale.setScalar(1);
    bullet.position.set(IMPACT_X + BULLET_V * (T_IMPACT - t), py, 0);
    bullet.rotation.set(-t * 38.0, 0, 0);
    bulletUniforms.uMush.value = 0;
  } else if (t < T_MUSH_END) {
    const m = smoothstep(T_IMPACT, T_MUSH_END, t);
    bullet.visible = true;
    bullet.scale.setScalar(1 - 0.12 * m);
    bullet.position.set(IMPACT_X, py, 0);
    bullet.rotation.set(-T_IMPACT * 38.0 - (t - T_IMPACT) * 12.0 * (1 - m), 0, 0);
    bulletUniforms.uMush.value = m;
  } else {
    const tau = t - T_MUSH_END;
    const k = 0.5;
    bullet.position.set(IMPACT_X + dragDisp(0.65, k, tau), py - gravDisp(1.6, k, tau), dragDisp(0.18, k, tau));
    bullet.rotation.set(-T_IMPACT * 38.0, 0.7 * tau, -1.4 * tau);
    bullet.scale.setScalar(0.88);
    bulletUniforms.uMush.value = 1;
    bullet.visible = bullet.position.y > -6;
  }

  // --- Glass: ringing, stress pulse, pre-fracture tension, running front ---
  const ring = t > T_IMPACT ? 0.016 * Math.exp(-(t - T_IMPACT) * 2.4) : 0;
  const ringPhase = 2 * Math.PI * 6.5 * (t - T_IMPACT);
  const pulse = smoothstep(T_DEBRIS_END, T_DEBRIS_END + 0.3, t) * (1 - smoothstep(3.7, 4.0, t));
  const pre = smoothstep(T_SNIP, T_SNIP + 0.3, t) * (1 - smoothstep(T_FRONT_START, T_FRONT_START + 0.25, t));
  const sFront = sFrontAt(t);
  const frontS = clamp01(sFront);
  const frontGlow = t >= T_FRONT_START ? (1 - smoothstep(T_FRONT_END, T_FRONT_END + 0.2, t)) : 0;
  spinePoint(frontS, _frontPos);
  const flash = smoothstep(T_SNIP, T_SNIP + 0.06, t) * Math.exp(-Math.max(0, t - T_SNIP - 0.06) * 6.5);
  for (let i = 0; i < glassMaterials.length; i++) {
    const u = glassMaterials[i].uniforms;
    u.uTime.value = t;
    u.uRing.value = ring;
    u.uRingPhase.value = ringPhase;
    u.uPulse.value = pulse;
    u.uPreTension.value = pre;
    u.uFlashInt.value = 7 * flash;
    u.uFlashPos.value.copy(P_CUT);
    u.uFrontGlow.value = frontGlow;
    u.uFrontPos.value.copy(_frontPos);
  }
  const bodyClip = t >= T_FRONT_START ? sFront : 2.0;
  bodyBack.material.uniforms.uSFront.value = sFront;
  bodyFront.material.uniforms.uSFront.value = sFront;
  bodyBack.material.uniforms.uSClip.value = bodyClip;
  bodyFront.material.uniforms.uSClip.value = bodyClip;
  bodyBack.visible = bodyFront.visible = t < T_FRONT_END;

  // --- Severed tail tip: at rest until the snip, then flung and tumbling ---
  let tipOpacity = 1;
  if (t < T_SNIP) {
    tipGroup.position.copy(TIP_CENTROID);
    tipGroup.quaternion.identity();
  } else {
    const tau = t - T_SNIP;
    const k = 0.6;
    tipGroup.position.set(
      TIP_CENTROID.x + dragDisp(0.35, k, tau),
      TIP_CENTROID.y + dragDisp(0.8, k, tau) - gravDisp(0.9, k, tau),
      TIP_CENTROID.z + dragDisp(0.25, k, tau));
    tipGroup.quaternion.setFromAxisAngle(_tipAxis, dragDisp(7.0, 0.8, tau));
    tipOpacity = 1 - smoothstep(0.9, 1.6, tau);
  }
  tipGroup.visible = tipOpacity > 0.002;
  tipBack.material.uniforms.uOpacity.value = tipOpacity;
  tipFront.material.uniforms.uOpacity.value = tipOpacity;

  // --- Nippers: approach, close onto the tail, snip, withdraw -------------
  let theta, retract;
  if (t < T_DEBRIS_END) { theta = 0.22; retract = 0.38; }
  else if (t < 3.3) { theta = 0.22; retract = 0.38 * (1 - smoothstep(T_DEBRIS_END, 3.3, t)); }
  else if (t < T_SNIP) { theta = 0.22 * (1 - smoothstep(3.3, T_SNIP, t)); retract = 0; }
