  else { const u = smoothstep(T_FRONT_START, 5.6, t); theta = 0.15 * u; retract = 0.9 * u; }
  jawA.rotation.z = -theta;
  jawB.rotation.z = theta;
  nipperGroup.position.copy(P_CUT).addScaledVector(NIP_D, retract);

  // --- Kinetic particle systems (shards, spall, dust, sparks) -------------
  for (let i = 0; i < kineticUniformSets.length; i++) kineticUniformSets[i].uTime.value = t;
  for (let i = 0; i < pointSystems.length; i++) pointSystems[i].uniforms.uTime.value = t;

  // --- Lights and glow sprites ---------------------------------------------
  flashLight.position.copy(P_CUT);
  flashLight.intensity = 10 * flash;
  setSprite(flashSprite, P_CUT, 0.3 + 1.1 * flash, flash);
  setSprite(flashCore, P_CUT, 0.12 + 0.35 * flash, flash);
  frontLight.position.copy(_frontPos);
  frontLight.intensity = frontGlow * (2.5 + 4.0 * smoothstep(0.35, 0.0, frontS));
  setSprite(frontSprite, _frontPos, 0.3 + 1.2 * (dropRadius(frontS) / BULB_R), frontGlow * 0.9);
  const impactGlow = smoothstep(T_IMPACT, T_IMPACT + 0.04, t) * Math.exp(-Math.max(0, t - T_IMPACT - 0.04) * 9);
  setSprite(impactSprite, _pos.set(IMPACT_X, py, 0), 0.25 + 0.6 * impactGlow, impactGlow * 0.9);

  renderer.render(scene, camera);
}

