// ---------------------------------------------------------------------------
// Analytic kinetic particle systems. Every particle carries a pre-seeded initial
// state; its pose at any simTime is evaluated on the GPU from that state alone
// (no per-frame CPU integration), so scrubbing is exact and instantaneous.
// ---------------------------------------------------------------------------
const KINETIC_GLSL = `
attribute vec3 aP0; attribute vec3 aVel; attribute vec4 aRot; attribute vec4 aMisc;
uniform float uTime; uniform vec3 uGravity; uniform float uDrag; uniform float uRotDrag;
mat3 kineticAxisRot(vec3 ax, float a) {
  float c = cos(a), s = sin(a), oc = 1.0 - c;
  return mat3(oc * ax.x * ax.x + c, oc * ax.x * ax.y + ax.z * s, oc * ax.z * ax.x - ax.y * s,
              oc * ax.x * ax.y - ax.z * s, oc * ax.y * ax.y + c, oc * ax.y * ax.z + ax.x * s,
              oc * ax.z * ax.x + ax.y * s, oc * ax.y * ax.z - ax.x * s, oc * ax.z * ax.z + c);
}
mat3 kineticRot; vec3 kineticPos; float kineticScale;
void kinetic() {
  float tau = uTime - aMisc.x;
  float alive = step(0.0, tau);
  tau = max(tau, 0.0);
  float ek = exp(-uDrag * tau);
  vec3 disp = aVel * (1.0 - ek) / uDrag + uGravity * (tau - (1.0 - ek) / uDrag) / uDrag;
  kineticPos = aP0 + disp;
  float ang = aRot.w * (1.0 - exp(-uRotDrag * tau)) / uRotDrag;
  kineticRot = kineticAxisRot(normalize(aRot.xyz), ang);
  kineticScale = alive * smoothstep(0.0, 0.05, tau);
}
`;
const kineticUniformSets = [];
function makeKineticMaterial(mat, opts) {
  const u = {
    uTime: { value: 0 },
    uGravity: { value: new THREE.Vector3(0, -opts.gravity, 0) },
    uDrag: { value: opts.drag },
    uRotDrag: { value: opts.rotDrag }
  };
  mat.onBeforeCompile = function (shader) {
    Object.assign(shader.uniforms, u);
    shader.vertexShader = KINETIC_GLSL + shader.vertexShader
      .replace('#include <beginnormal_vertex>', 'kinetic();\nvec3 objectNormal = kineticRot * normal;')
      .replace('#include <begin_vertex>', 'vec3 transformed = kineticRot * (position * aMisc.yzw * kineticScale) + kineticPos;');
  };
  mat.customProgramCacheKey = function () { return 'kinetic-' + mat.type; };
  kineticUniformSets.push(u);
  return mat;
}
function addInstanceAttributes(geometry, count) {
  const p0 = new Float32Array(count * 3), vel = new Float32Array(count * 3);
  const rot = new Float32Array(count * 4), misc = new Float32Array(count * 4);
  geometry.setAttribute('aP0', new THREE.InstancedBufferAttribute(p0, 3));
  geometry.setAttribute('aVel', new THREE.InstancedBufferAttribute(vel, 3));
  geometry.setAttribute('aRot', new THREE.InstancedBufferAttribute(rot, 4));
  geometry.setAttribute('aMisc', new THREE.InstancedBufferAttribute(misc, 4));
