const KINETIC_GLSL = `
attribute vec3 aP0; attribute vec3 aVel; attribute vec4 aRot; attribute vec4 aMisc;
uniform float uTime; uniform vec3 uGravity; uniform float uDrag; uniform float uRotDrag;
