  float ek = exp(-uDrag * tau);
  vec3 disp = aVel * (1.0 - ek) / uDrag + uGravity * (tau - (1.0 - ek) / uDrag) / uDrag;
  kineticPos = aP0 + disp;
  float ang = aRot.w * (1.0 - exp(-uRotDrag * tau)) / uRotDrag;
