  g.rotateZ(-Math.PI / 2);   // nose at the origin, base at +X, flying toward -X
  const pos = g.getAttribute('position');
  const col = new Float32Array(pos.count * 3);
  for (let i = 0; i < pos.count; i++) {
    const lead = (pos.getX(i) / BULLET_LEN) < 0.42;   // dull lead nose, copper jacket behind
    col[i * 3] = lead ? 0.58 : 0.80;
    col[i * 3 + 1] = lead ? 0.60 : 0.50;
