// Spine sampling weighted by local glass volume (more fragments in the bulb)
const spineCDF = (() => {
  const n = 600;
  const cdf = new Float64Array(n + 1);
  for (let i = 1; i <= n; i++) {
    const r = dropRadius(((i - 0.5) / n) * S_CUT);
    cdf[i] = cdf[i - 1] + Math.pow(r, 1.3) + 0.002;
  }
  for (let i = 1; i <= n; i++) cdf[i] /= cdf[n];
  return { cdf, n };
})();
