  sys.vel[i * 3] = vx; sys.vel[i * 3 + 1] = vy; sys.vel[i * 3 + 2] = vz;
  sys.misc[i * 4] = tSpawn; sys.misc[i * 4 + 1] = size; sys.misc[i * 4 + 2] = life; sys.misc[i * 4 + 3] = rand();
}

