  const s = sampleBodyS();
  const r = dropRadius(s);
  spinePoint(s, _fC);
  radialAt(s, rand() * Math.PI * 2, _fR);
  const rfrac = Math.sqrt(rand());
  const rel = r / BULB_R;
  const speed = (0.5 + 2.2 * rel) * randRange(0.3, 1.3);
  const along = randRange(-0.5, 0.5);
  setPoint(dust, i,
    _fC.x + _fR.x * r * rfrac, _fC.y + _fR.y * r * rfrac, _fC.z + _fR.z * r * rfrac,
    _fR.x * speed + _fT.x * along + randRange(-0.25, 0.25),
    _fR.y * speed + _fT.y * along + randRange(-0.25, 0.25),
    _fR.z * speed + _fT.z * along + randRange(-0.25, 0.25),
