  const sph = d < 2 * R ? Math.sqrt(Math.max(0, R * R - (d - R) * (d - R))) : 0;
  const neck = (0.535 * Math.exp(-d * 1.035) + 0.03) * smoothstep(0.2, 0.7, d);   // long teardrop taper
  let r = smax(sph, neck, 0.18);
