      aT[vi * 3] = T.x; aT[vi * 3 + 1] = T.y; aT[vi * 3 + 2] = T.z;
      aN1[vi * 3] = N1.x; aN1[vi * 3 + 1] = N1.y; aN1[vi * 3 + 2] = N1.z;
