  g.setAttribute('aRadius', new THREE.BufferAttribute(aR, 1));
  g.setAttribute('aCenter', new THREE.BufferAttribute(aC, 3));
  g.setAttribute('aTangent', new THREE.BufferAttribute(aT, 3));
  g.setAttribute('aN1', new THREE.BufferAttribute(aN1, 3));
  g.setIndex(new THREE.BufferAttribute(idx, 1));
  return g;
}

// ---------------------------------------------------------------------------
// Quenched glass shader: PMREM studio reflections, Fresnel, cross-polarised
// photoelastic isochromatic fringes, elastic ringing, fracture-front clipping
// ---------------------------------------------------------------------------
const GLASS_VERT = `
attribute float aS; attribute float aRadius;
attribute vec3 aCenter; attribute vec3 aTangent; attribute vec3 aN1;
uniform float uRing; uniform float uRingPhase; uniform float uSImpact; uniform float uSpineLen;
varying vec3 vWorldPos; varying vec3 vNormal; varying float vS; varying float vRadius;
