// Main body (s in [0, S_CUT]) and the tail tip that gets snipped off (s in [S_CUT, 1])
const bodyGeom = buildTubeGeometry(0, S_CUT, 340);
const bodyBack = new THREE.Mesh(bodyGeom, makeGlassMaterial(true));
const bodyFront = new THREE.Mesh(bodyGeom, makeGlassMaterial(false));
bodyBack.renderOrder = 1; bodyFront.renderOrder = 2;
scene.add(bodyBack, bodyFront);

const tipGeom = buildTubeGeometry(S_CUT, 1, 40);
