// ---------------------------------------------------------------------------
// Prince Rupert's Drop spine, parameterised by normalised arc length s in [0,1]
// (s = 0 bulb pole at the bottom, s = 1 helical tail tip at the top)
// ---------------------------------------------------------------------------
function spineRaw(t, out) {
  const y0 = -1.72, y1 = 1.52;
  const y = y0 + (y1 - y0) * t;
  const lean = 0.46 * t * t;                 // gentle diagonal lean to the right
  const u = smoothstep(0.64, 1.0, t);        // helical tail region
  const hr = 0.2 * u;
  const ang = u * Math.PI * 2.2;
  out.set(lean + hr * (Math.cos(ang) - 1.0), y, hr * Math.sin(ang));
  return out;
}
const spineTable = (() => {
  const N = 2400;
  const pts = new Array(N + 1);
  const cum = new Float64Array(N + 1);
  for (let i = 0; i <= N; i++) {
    pts[i] = spineRaw(i / N, new THREE.Vector3());
    if (i > 0) cum[i] = cum[i - 1] + pts[i].distanceTo(pts[i - 1]);
  }
  return { pts, cum, length: cum[N], N };
})();
const SPINE_LEN = spineTable.length;
const BULB_R = 0.5;
const S_IMPACT = BULB_R / SPINE_LEN;        // bulb centre (impact site) as spine parameter

function spinePoint(s, out) {
  const d = clamp01(s) * SPINE_LEN;
  const cum = spineTable.cum;
  let lo = 0, hi = spineTable.N;
  while (hi - lo > 1) { const mid = (lo + hi) >> 1; if (cum[mid] <= d) lo = mid; else hi = mid; }
  const seg = cum[hi] - cum[lo];
  const f = seg > 1e-9 ? (d - cum[lo]) / seg : 0;
  return out.copy(spineTable.pts[lo]).lerp(spineTable.pts[hi], f);
