const _ta = new THREE.Vector3(), _tb = new THREE.Vector3();
function spineTangent(s, out) {
  const e = 0.002;
  spinePoint(Math.max(0, s - e), _ta);
  spinePoint(Math.min(1, s + e), _tb);
  return out.subVectors(_tb, _ta).normalize();
}
function smax(a, b, k) { const h = clamp01(0.5 + 0.5 * (a - b) / k); return lerp(b, a, h) + k * h * (1 - h); }
function dropRadius(s) {
  const d = clamp01(s) * SPINE_LEN;
  const R = BULB_R;
  const sph = d < 2 * R ? Math.sqrt(Math.max(0, R * R - (d - R) * (d - R))) : 0;
  const neck = (0.535 * Math.exp(-d * 1.035) + 0.03) * smoothstep(0.2, 0.7, d);   // long teardrop taper
  let r = smax(sph, neck, 0.18);
