// Camera framing: fixed, looking along -Z, drop within the central 70% for 16:9 and 1280x1340
const dropBounds = (() => {
  const b = new THREE.Box3();
  const p = new THREE.Vector3();
  for (let i = 0; i <= 400; i++) {
    const s = i / 400;
