      uFringeAmt: { value: 0.17 }, uPulse: { value: 0 }, uPreTension: { value: 0 }, uSCut: { value: S_CUT },
      uRing: { value: 0 }, uRingPhase: { value: 0 }, uSImpact: { value: S_IMPACT }, uSpineLen: { value: SPINE_LEN },
      uOpacity: { value: 1 }, uBackPass: { value: backPass ? 1 : 0 },
      uFlashPos: { value: new THREE.Vector3() }, uFlashInt: { value: 0 }, uFrontPos: { value: new THREE.Vector3() },
